OCALERT='<div class="alertbox" id="occ-alert" hidden><h2>Get an email when holiday let rules change in <span id="occ-an">your nation</span></h2><p id="occ-why">We track these rules against official sources and email you when one of them changes.</p><p class="small">Plus one short weekly UK "what changed" email. Free. Unsubscribe any time.</p>'+FORMX.replace('<form class="signup"','<form class="signup" id="occ-form" data-cta="occupancy-result" data-area="" data-area-name=""',1).replace('>Subscribe<','>Get free alerts<')+'</div>'
OCWHY={'wales':'We track the Welsh business rates and council tax rules for holiday lets against official sources, and email you when they change. The Welsh Government consulted until 30 October 2026 on how self-catering properties are classified, including whether 182 days is the right threshold, and will publish the outcome.',
 'england':'We track the business rates and council tax rules for holiday lets in England against official sources, and email you when they change, including the 140/70-night tests and second homes premiums.',
 'scotland':'We track the Scottish business rates and council tax rules for short-term lets against official sources, and email you when they change, including the 140/70-night test and the Assessor evidence deadline (before 27 May each year).'}
_opts=''.join(f'<option value="{k}">{v["name"]} ({v["av"]} available / {v["let"]} let)</option>' for k,v in OC.items())
OCJS='''<script>(function(){var O=__O__,W=__W__,$=function(i){return document.getElementById(i)};
function fd(d){return d.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}
function sync(){var o=O[$('on').value];$('ope').textContent='Counting period: '+o.period+'.';if($('on').value=='scotland'&&!$('oe').value){var t=new Date(),y=t.getMonth()>2?t.getFullYear()+1:t.getFullYear();$('oe').value=y+'-03-31'}}
$('on').addEventListener('change',sync);sync();
$('ogo').addEventListener('click',function(){var o=O[$('on').value],l=parseInt($('ol').value||0),a=parseInt($('oa').value||0),e=$('oe').value;
 if(!e){alert('Please enter the end date of your 12-month period.');return}
 var end=new Date(e+'T23:59:59'),now=new Date(),left=Math.max(0,Math.ceil((end-now)/864e5)),nl=Math.max(0,o.let-l),na=Math.max(0,o.av-a);
 var h,ok=nl==0&&na==0;
 if(ok)h='You have reached both thresholds ('+o.av+' available, '+o.let+' let).';
 else h='You need '+(nl?nl+' more let night'+(nl>1?'s':''):'no more let nights')+(na?' and '+na+' more available night'+(na>1?'s':''):'')+' by '+fd(end)+'.';
 var warn=(!ok&&(nl>left||na>left))?' There are only '+left+' nights left in the period, so the shortfall cannot be made up from new nights alone.':(!ok?' '+left+' nights left in the period.':'');
 $('orh').textContent=h;$('orw').textContent=warn;
 $('oal').innerHTML=o.allow.map(function(x){return '<li>'+x+'</li>'}).join('');$('omiss').textContent=o.miss;
 $('osrc').innerHTML='Sources: '+o.src.map(function(u){return '<a href="'+u+'" rel="nofollow">'+u.replace('https://','').split('/')[0]+'</a>'}).join(', ');
 var body='Holiday let business rates check ('+o.name+')\\n\\nThreshold: '+o.av+' nights available and '+o.let+' nights let in '+o.period+'.\\nSo far: '+a+' available, '+l+' let.\\nPeriod ends: '+fd(end)+'.\\nResult: '+h+warn+'\\nIf missed: '+o.miss+'\\n\\nSource: '+o.src[0]+'\\nWorked out with the free tracker at https://ukshortletrules.co.uk/occupancy-threshold-tracker (general information, not tax advice).';
 $('omail').href='mailto:?subject='+encodeURIComponent('Holiday let business rates threshold: '+o.name)+'&body='+encodeURIComponent(body);
 $('or').hidden=false;
 var A=$('occ-alert'),F=$('occ-form'),S=document.querySelector('section.alertcta'),k=$('on').value;if(A&&F){if(F.getAttribute('data-area')!='nation:'+k){var M=F.querySelector('.msg');if(M)M.textContent=''}F.setAttribute('data-area','nation:'+k);F.setAttribute('data-area-name',o.name);$('occ-an').textContent=o.name;$('occ-why').textContent=W[k];A.hidden=false;if(S)S.hidden=true}
 try{gtag('event','occupancy_check',{nation:k,met:ok?'yes':'no'})}catch(x){}});
})();</script>'''.replace('__O__',_j.dumps(OC)).replace('__W__',_j.dumps(OCWHY))
# Common questions (visible + FAQPage JSON-LD). Built inline (guides.py shadows FAQ() with a list). Sources re-checked 31 Oct 2026:
# GOV.UK "Apply for business rates for a self-catering property in England" (updated 29 Sep 2026) and "... in Wales" (updated 9 Oct 2026);
# mygov.scot non-domestic rates: self-catering (updated 30 Mar 2026); Scottish Assessors self-catering page; legislation.gov.uk ssi/2026/72 (reg 5A),
# wsi/2026/7 (Wales averaging + charity nights, in force 1 Apr 2026); gov.wales consultation "Classification of self-catering properties for local tax
# purposes" (closed 30 Oct 2026, reviewing responses); gov.wales council tax empty and second homes (premium up to 300%); legislation.gov.uk ukpga/2015/20 s.44;
# HMRC FHL abolition policy paper and clarification.
OCQ=[('What are the occupancy thresholds for business rates?','England: available to let commercially for at least 140 nights and actually let for at least 70 nights in a 12-month period, and you intend to make it available for 140 nights in the next 12 months. Scotland: 140 nights available and 70 let in the financial year (1 April to 31 March), and it must not be anyone\'s only or main residence. Wales: 252 nights available and 182 let in a 12-month period, and you intend to make it available for 252 nights in the next 12 months.'),
 ('What counts as a let night?','In England and Wales, count nights let commercially (to make a profit) in stays of 28 nights or less. Nights in a longer stay do not count towards the let nights, but can count towards the available nights if the property could have been booked for 28 nights or less. You cannot count nights closed for repair or refurbishment, nights the site was closed, your own use, discounted lets to friends or family, or future bookings. In Scotland, non-commercial lets to family and friends do not count, and any booking over 28 nights needs an explanation in your evidence.'),
 ('What happens if I miss the threshold?','The property is taxed as a home instead. In England it is valued for council tax, and many councils charge a second homes premium. In Scotland it goes on the council tax list for that financial year. In Wales it may be moved to council tax, where councils can charge a second homes premium of up to 300%.'),
 ('My Welsh holiday let was not let for 182 nights. Is there any flexibility?','Yes, in some cases. If you own several self-catering lets in the same location or very near each other, you can average the nights let across them. From 1 April 2026 you can also use the average over the previous 24 or 36 months, as long as it is at least 182 nights a year, and count up to 14 nights a year donated to a registered charity. Explain any averaging in the remarks section of the application form.'),
 ('Is the Welsh 182-day rule changing?','Not yet. The Welsh Government consulted from 31 July to 30 October 2026 on how self-catering properties are classified for local tax, including whether 182 days is the right threshold and 5 proposed exemptions. The consultation has closed and GOV.WALES says it is reviewing responses and will publish the outcome. Until then the current 252/182 rules apply.'),
 ('Are there exceptions in England for bigger sites?','Yes, from 24 July 2026. If you own 5 or more self-catering lets that are part of the same property, none is anyone\'s main residence, and you intend to make each available for 140 days over the next 12 months, they qualify without meeting the 140/70 history test. A holiday let that shares land with a different business run by the same owner can qualify on the same intention.'),
 ('When do I send evidence to the Assessor in Scotland?','Evidence for each financial year must reach your local Assessor before 27 May the following year (so by 26 May), or within 56 days of an Assessor request made after the year end, if that is later. Late evidence cannot be considered. You do not have to wait to be asked: you can send a self-catering declaration on the Scottish Assessors website at any time.'),
 ('What records should I keep?','Keep booking calendars showing the nights you were available, your listings or adverts, and every booking with its dates and the income received (a booking summary from your platform helps). If you take direct bookings, keep bank statements showing guest payments, and note the reason for any stay over 28 nights. The Scottish Assessors ask for these, and they back up a business rates application in England and Wales too.'),
 ('Did the end of the FHL tax regime change these tests?','No. The furnished holiday lettings tax regime ended from 6 April 2025 for Income Tax and Capital Gains Tax (1 April 2025 for Corporation Tax). HMRC says this does not affect council tax or business rates, so the business rates thresholds above still apply. The London 90-night limit is also separate: it is a planning rule in Greater London (up to 90 nights per calendar year without planning permission).')]
OCQLD=json.dumps({'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in OCQ]}).replace('</','<\\/')
OCQH=('<h2 id="occ-faq">Common questions</h2><div class="faq">'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in OCQ)+'</div>'
 +'<p class="small">More detail: <a href="scotland-business-rates-checker">Scotland business rates checker</a> · <a href="england-second-homes-council-tax-premium">England second homes premium</a> · <a href="wales-second-homes-council-tax-premium">Wales second homes premium</a> · <a href="wales">Wales rules</a> · <a href="holiday-let-tax-after-fhl-abolition">Holiday let tax after the FHL abolition</a> · <a href="london-90-night-counter">London 90-night counter</a> · <a href="deadlines">Deadlines</a>.</p>'
 +'<p class="small">Sources: <a href="https://www.gov.uk/guidance/apply-for-business-rates-for-a-self-catering-property-in-england" rel="nofollow">GOV.UK: business rates for self-catering in England</a>, <a href="https://www.gov.uk/guidance/apply-for-business-rates-for-a-self-catering-property-in-wales" rel="nofollow">GOV.UK: business rates for self-catering in Wales</a>, <a href="https://www.legislation.gov.uk/wsi/2026/7/made" rel="nofollow">WSI 2026/7</a>, <a href="https://www.gov.wales/classification-self-catering-properties-local-tax-purposes" rel="nofollow">Welsh Government: self-catering classification consultation</a>, <a href="https://www.gov.wales/council-tax-empty-and-second-homes-html" rel="nofollow">Welsh Government: council tax premiums</a>, <a href="https://www.mygov.scot/non-domestic-rates-guidance/short-term-lets" rel="nofollow">mygov.scot: self-catering and non-domestic rates</a>, <a href="https://www.saa.gov.uk/non-domestic-valuation/self-catering/" rel="nofollow">Scottish Assessors: self-catering</a>, <a href="https://www.legislation.gov.uk/ssi/2026/72/made" rel="nofollow">SSI 2026/72</a>, <a href="https://www.gov.uk/government/publications/furnished-holiday-lettings-tax-regime-abolition/clarification-on-abolition-of-the-furnished-holiday-lettings-tax-regime" rel="nofollow">HMRC: FHL abolition clarification</a>, <a href="https://www.legislation.gov.uk/ukpga/2015/20/section/44" rel="nofollow">Deregulation Act 2015, section 44</a>. Source: Welsh Government rules (WSI 2026/7). Checked 31 Oct 2026.</p>')
_tab=''.join(f'<tr><td>{v["name"]}</td><td>{v["av"]} nights</td><td>{v["let"]} nights</td><td>{v["period"]}</td><td>{" ".join(f"<a href=\"{u}\" rel=\"nofollow\">source</a>" for u in v["src"])}</td></tr>' for v in OC.values())
page('occupancy-threshold-tracker.html','Holiday let occupancy threshold tracker',f'''<p class="lead">Are you on track for business rates? Enter your nights so far and the end of your 12-month period to see how many more let nights you need, the allowances that apply and what happens if you miss. Rules from GOV.UK, mygov.scot and the Scottish Assessors, checked {C}.</p>
<div class="card"><form class="lvf" onsubmit="return false">
<label for="on">Where is the property?</label><select id="on">{_opts}</select><p class="small" id="ope"></p>
<label for="ol">Nights let so far (stays of 28 nights or less)</label><input type="number" id="ol" min="0" max="366" inputmode="numeric" value="0">
<label for="oa">Nights available to let so far</label><input type="number" id="oa" min="0" max="366" inputmode="numeric" value="0">
<label for="oe">End date of the 12-month period</label><input type="date" id="oe">
<button type="button" id="ogo">Check my nights</button></form>
<div id="or" hidden aria-live="polite"><h2 id="orh"></h2><p id="orw"></p><h3>Allowances and what counts</h3><ul id="oal"></ul><h3>If you miss the threshold</h3><p id="omiss"></p><p><a class="btn" id="omail" href="#">Send to my accountant</a> <span class="small">Opens your email app with a summary. Nothing is sent by this site.</span></p><p class="small" id="osrc"></p><p class="small"><b>Estimate, not tax advice.</b> The valuation office or Assessor decides. Keep booking records as evidence.</p></div>{OCALERT}</div>
<h2>Thresholds</h2><div class="tw"><table><tr><th>Nation</th><th>Available</th><th>Let</th><th>Period</th><th>Official source</th></tr>{_tab}</table></div>
<p>Northern Ireland uses a different system: see the <a href="northern-ireland.html">Northern Ireland page</a>. For Scotland, try the <a href="scotland-business-rates-checker.html">Scotland business rates checker</a>.</p>
{OCQH}{OCJS}''',desc='Free tracker for the holiday let business rates tests: Wales 252/182 nights, England and Scotland 140/70. See how many more let nights you need, allowances, and email a summary to your accountant.',full_title='Holiday let occupancy threshold tracker (182/252 and 140/70 nights) | UK Short-Let Rules',head='<script type="application/ld+json">'+OCQLD+'</script>')
